module voodoo_counter (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [2:0] N,\n    input wire [7:0] P,\n    input wire [7:0] arr_0, arr_1, arr_2, arr_3,\n                 arr_4, arr_5, arr_6, arr_7,\n    output reg [5:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE        = 3'd0;\n    localparam [2:0] INIT        = 3'd1;\n    localparam [2:0] PREFIX      = 3'd2;\n    localparam [2:0] COUNT_INIT  = 3'd3;\n    localparam [2:0] COUNT_LOOP  = 3'd4;\n    localparam [2:0] DONE_STATE  = 3'd5;\n\n    // Internal registers\n    reg [2:0] state, next_state;\n    reg signed [11:0] prefix [0:8];  // 9 elements, 12-bit signed\n    reg [3:0] i_cnt, j_cnt;\n    reg [5:0] temp_result;\n    reg [7:0] cycle_count;\n    wire signed [8:0] b_i;  // arr_i - P (9-bit signed)\n\n    // Array selector\n    wire [7:0] sel_arr = (i_cnt == 3'd0) ? arr_0 :\n                         (i_cnt == 3'd1) ? arr_1 :\n                         (i_cnt == 3'd2) ? arr_2 :\n                         (i_cnt == 3'd3) ? arr_3 :\n                         (i_cnt == 3'd4) ? arr_4 :\n                         (i_cnt == 3'd5) ? arr_5 :\n                         (i_cnt == 3'd6) ? arr_6 :\n                         arr_7;\n\n    assign b_i = {1'b0, sel_arr} - {1'b0, P};\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize ALL registers\n            state <= IDLE;\n            result <= 6'd0;\n            done <= 1'b0;\n            temp_result <= 6'd0;\n            i_cnt <= 4'd0;\n            j_cnt <= 4'd0;\n            cycle_count <= 8'd0;\n            // Initialize prefix array\n            begin : INIT_PREFIX\n                integer i;\n                for (i = 0; i < 9; i = i + 1) begin\n                    prefix[i] <= 12'sd0;\n                end\n            end\n        end else begin\n            cycle_count <= cycle_count + 8'd1;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= INIT;\n                        cycle_count <= 8'd0;\n                    end\n                end\n\n                INIT: begin\n                    prefix[0] <= 12'sd0;\n                    i_cnt <= 4'd0;\n                    state <= PREFIX;\n                end\n\n                PREFIX: begin\n                    if (i_cnt < N) begin\n                        if (cycle_count[0]) begin  // 2-cycle operation\n                            prefix[i_cnt+1] <= prefix[i_cnt] + b_i;\n                            i_cnt <= i_cnt + 4'd1;\n                        end\n                    end else begin\n                        state <= COUNT_INIT;\n                        cycle_count <= 8'd0;\n                    end\n                end\n\n                COUNT_INIT: begin\n                    i_cnt <= 4'd0;\n                    j_cnt <= 4'd1;\n                    temp_result <= 6'd0;\n                    state <= COUNT_LOOP;\n                end\n\n                COUNT_LOOP: begin\n                    if (i_cnt < N) begin\n                        if (j_cnt <= N) begin\n                            if (prefix[i_cnt] <= prefix[j_cnt]) begin\n                                temp_result <= temp_result + 6'd1;\n                            end\n                            j_cnt <= j_cnt + 4'd1;\n                        end else begin\n                            i_cnt <= i_cnt + 4'd1;\n                            j_cnt <= i_cnt + 4'd1 + 4'd1;\n                        end\n                    end else begin\n                        result <= temp_result;\n                        state <= DONE_STATE;\n                    end\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\nendmodule